fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // We're guaranteed that `v` is non-empty, sorted in non-decreasing order,
    // and that `k` appears at least once.
    let mut lo = 0;
    let mut hi = v.len();

    // Invariant: the target k is in v[lo..hi]
    while lo < hi {
        // Avoid potential overflow by computing mid this way
        let mid = lo + (hi - lo) / 2;
        if v[mid] < k {
            // k must be in v[mid+1..hi]
            lo = mid + 1;
        } else {
            // k is in v[lo..=mid]
            hi = mid;
        }
    }

    // lo is the smallest index such that v[lo] >= k.
    // Because k is guaranteed to be present, v[lo] == k.
    lo
}

